H.background();
const w = H.W, h = H.H;
// Photoelectric effect: a photon of energy hf hits a metal; if hf > work function W,
// an electron escapes with KE = hf - W.  h*f in eV, work function in eV.
const f = P.freq;            // light frequency, x10^14 Hz
const Wf = P.work;           // work function, eV
const I = P.intensity;       // light intensity (number of photons), arbitrary
const h_eV = 4.136e-15;      // Planck constant in eV*s
const Ephoton = h_eV * (f * 1e14);   // photon energy in eV
const KE = Ephoton - Wf;     // ejected electron kinetic energy, eV
const ejects = KE > 0;
// metal slab on the right
const metalX = w * 0.62;
H.rect(metalX, h * 0.18, w * 0.30, h * 0.64, { fill: "#33405e", stroke: H.colors.axis, width: 2, radius: 6 });
H.text("metal surface", metalX + 10, h * 0.18 - 10, { color: H.colors.sub, size: 12 });
// incoming photon (wave packet) loops in toward the surface
const period = 2.2;
const ph = (t % period) / period;          // 0..1
const px = H.lerp(w * 0.08, metalX, ph);
const py = h * 0.5;
// draw the photon as a little oscillating wave segment
const pts = [];
for (let i = 0; i <= 40; i++) {
  const xx = px - 60 + i * 1.5;
  const yy = py + 10 * Math.sin((i / 40) * H.TAU * 3 + t * 8);
  if (xx < metalX) pts.push([xx, yy]);
}
if (pts.length >= 2) H.path(pts, { color: H.colors.yellow, width: 2.5 });
H.circle(px, py, 6, { fill: H.colors.yellow });
// bound electrons sitting in the metal
for (let i = 0; i < 5; i++) {
  H.circle(metalX + 30 + (i % 3) * 36, h * 0.30 + Math.floor(i / 3) * 60 + 2 * Math.sin(t * 2 + i), 7, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
}
// ejected electron flies LEFT out of the metal after the photon arrives, then resets
if (ejects && ph > 0.5) {
  const ej = (ph - 0.5) / 0.5;             // 0..1
  const speedScale = Math.sqrt(Math.max(0, KE));
  const ex = metalX - ej * (metalX - w * 0.12) * H.clamp(speedScale, 0.3, 1.5) / 1.5;
  const ey = py - ej * 40;
  H.arrow(metalX, py, ex, ey, { color: H.colors.good, width: 2.5, head: 9 });
  H.circle(ex, ey, 7, { fill: H.colors.good, stroke: H.colors.bg, width: 2 });
  H.text("e-", ex - 4, ey - 12, { color: H.colors.good, size: 12 });
}
// title + readouts
H.text("Photoelectric effect: KE = h·f − W", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("photon energy  h·f = " + Ephoton.toFixed(2) + " eV", 24, 56, { color: H.colors.sub, size: 13 });
H.text("work function  W = " + Wf.toFixed(2) + " eV", 24, 76, { color: H.colors.sub, size: 13 });
if (ejects) {
  H.text("KE = h·f − W = " + KE.toFixed(2) + " eV  → electron ejected", 24, 96, { color: H.colors.good, size: 13 });
} else {
  H.text("h·f < W  → no electron ejected (below threshold)", 24, 96, { color: H.colors.warn, size: 13 });
}
H.text("intensity sets HOW MANY electrons, never their KE", 24, h - 18, { color: H.colors.sub, size: 12 });
H.legend([{ label: "photon", color: H.colors.yellow }, { label: "electron", color: H.colors.good }], w - 150, 28);
